(7251644, 1126954, 121111, '<td valign="top">beautiful scene!<br/> <br/>Personally i would have left the cloudd go a bit brighter, but that''s just me</td>', 'beautiful scene! Personally i would have left the cloudd go a bit brighter, but that''s just me', '2014-08-15 10:07:44.000000', NULL, 1),
(7251646, 1127246, 121111, '<td valign="top">Gorgeous scene<br/>very well processed</td>', 'Gorgeous scenevery well processed', '2014-08-15 10:10:02.000000', NULL, 1),
(7251647, 1127236, 121111, '<td valign="top">great subject<br/>very nicely processed<br/> <br/>dying here to slide the contrast and clarity a touch to the right, at least on the water / sand<br/>8</td>', 'great subjectvery nicely processed dying here to slide the contrast and clarity a touch to the right, at least on the water / sand8', '2014-08-15 10:12:43.000000', NULL, 1),
(7251648, 1127278, 121111, '<td valign="top">Excellent processing !<br/> <br/>very nice flowery weed highlighted by the sun light, impressive depth of field<br/> <br/>absolutely no trace of any movement of the grass, and no trace of it being more than one exposure<br/> <br/>love the mountains in the far away background <br/>9</td>', 'Excellent processing ! very nice flowery weed highlighted by the sun light, impressive depth of field absolutely no trace of any movement of the grass, and no trace of it being more than one exposure love the mountains in the far away background 9', '2014-08-15 10:15:31.000000', NULL, 1),
(7251650, 1127238, 121111, '<td valign="top">surreal !</td>', 'surreal !', '2014-08-15 10:16:18.000000', NULL, 1),
(7251651, 1127140, 121111, '<td valign="top">wish I was there!</td>', 'wish I was there!', '2014-08-15 10:16:54.000000', NULL, 1),
(7251652, 1127329, 121111, '<td valign="top">wonderful long shadows , well done !</td>', 'wonderful long shadows , well done !', '2014-08-15 10:17:50.000000', NULL, 1),
(7251653, 1127288, 121111, '<td valign="top">Gorgeous scene<br/>top 10 for me</td>', 'Gorgeous scenetop 10 for me', '2014-08-15 10:18:38.000000', NULL, 1),
(7251654, 1127262, 121111, '<td valign="top">intriguing lines !</td>', 'intriguing lines !', '2014-08-15 10:18:58.000000', NULL, 1),
(7251655, 1127270, 121111, '<td valign="top">for hdr I would have liked to see more detail int eh bights and darks, but I really like the scene so ... <br/>8</td>', 'for hdr I would have liked to see more detail int eh bights and darks, but I really like the scene so ... 8', '2014-08-15 10:20:06.000000', NULL, 1),
(7251656, 1127325, 121111, '<td valign="top">nicely controlled saturation of the greens , wishing it had more contrast, and that there was a more defined subject<br/>7</td>', 'nicely controlled saturation of the greens , wishing it had more contrast, and that there was a more defined subject7', '2014-08-15 10:21:10.000000', NULL, 1),
(7251658, 1127006, 121111, '<td valign="top">tight <br/> <br/>I''ve seen myself in situations like this, I can feel the frustration trying to get a better framing and bumping into something<br/> <br/>awesome depth of field<br/>no distortions<br/>very well processed, <br/>only wish there was more detail in the highlights</td>', 'tight  I''ve seen myself in situations like this, I can feel the frustration trying to get a better framing and bumping into something awesome depth of fieldno distortionsvery well processed, only wish there was more detail in the highlights', '2014-08-15 10:23:30.000000', NULL, 1),
(7251659, 1127340, 121111, '<td valign="top">nice symmetric lines<br/>nicely controlled highlights and shadows<br/>well done!</td>', 'nice symmetric linesnicely controlled highlights and shadowswell done!', '2014-08-15 10:26:58.000000', NULL, 1),
(7251660, 1127239, 121111, '<td valign="top">Very nice, tranquil place, looks like my neck of the "woods"<br/>Nice addition of the person on the path <br/>I would have added a touch more contrast, but that''s me<br/>this would have worked nicely in vanishing point :) but I hardly ever have the ideal image for the time of a particular challenge<br/> <br/>7</td>', 'Very nice, tranquil place, looks like my neck of the "woods"Nice addition of the person on the path I would have added a touch more contrast, but that''s methis would have worked nicely in vanishing point :) but I hardly ever have the ideal image for the time of a particular challenge 7', '2014-08-15 10:29:45.000000', NULL, 1),
(7251661, 1127291, 121111, '<td valign="top">colorful!<br/>love the sea surface</td>', 'colorful!love the sea surface', '2014-08-15 10:30:44.000000', NULL, 1),
(7251662, 1127311, 121111, '<td valign="top">great framing!</td>', 'great framing!', '2014-08-15 10:32:24.000000', NULL, 1),
