(7251664, 1126954, 112739, '<td valign="top">A view a guy can live for. Excellent work.</td>', 'A view a guy can live for. Excellent work.', '2014-08-15 10:34:57.000000', NULL, 1),
(7251666, 1127278, 112739, '<td valign="top">Top 3</td>', 'Top 3', '2014-08-15 10:37:18.000000', NULL, 1),
(7251676, 1127006, 23484, '<td valign="top">Very nice job on the HDR.</td>', 'Very nice job on the HDR.', '2014-08-15 11:38:59.000000', NULL, 1),
(7251677, 1127144, 23484, '<td valign="top">Very well done.</td>', 'Very well done.', '2014-08-15 11:39:22.000000', NULL, 1),
(7251679, 1127278, 23484, '<td valign="top">Beautiful landscape. Very nice job.</td>', 'Beautiful landscape. Very nice job.', '2014-08-15 11:40:15.000000', NULL, 1),
(7251682, 1127238, 23484, '<td valign="top">Absolutely gorgeous composition.</td>', 'Absolutely gorgeous composition.', '2014-08-15 11:43:48.000000', NULL, 1),
(7251687, 1127215, 16046, '<td valign="top">Best in show award, congrats</td>', 'Best in show award, congrats', '2014-08-15 11:59:30.000000', NULL, 1),
