INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7252812, 1126991, 34114, '<td valign="top">Lovely textures and feel! Good luck!</td>', 'Lovely textures and feel! Good luck!', '2014-08-19 07:16:34.000000', NULL, 1),
(7252834, 1126991, 19825, '<td valign="top">A fascinating scene -- I love the texture and contrast of beauty and the beast. If I were to offer one suggestion, the dark areas look a little washed out. I might try bring up the black levels a bit.</td>', 'A fascinating scene -- I love the texture and contrast of beauty and the beast. If I were to offer one suggestion, the dark areas look a little washed out. I might try bring up the black levels a bit.', '2014-08-19 11:17:03.000000', NULL, 1),
(7252835, 1127224, 19825, '<td valign="top">Interesting POV and lines. Can I borrow this field for the Purple challenge&gt;</td>', 'Interesting POV and lines. Can I borrow this field for the Purple challenge>', '2014-08-19 11:22:39.000000', NULL, 1),
(7252836, 1127210, 19825, '<td valign="top">I am not sure how this scene was enhanced with HDR, but I like your eye.</td>', 'I am not sure how this scene was enhanced with HDR, but I like your eye.', '2014-08-19 11:24:05.000000', NULL, 1),
(7252879, 1127240, 101668, '<td valign="top">so very nice</td>', 'so very nice', '2014-08-19 16:27:41.000000', NULL, 1),
(7252917, 1127097, 65480, '<td valign="top">Not a bad photo but I don''t see much HDR</td>', 'Not a bad photo but I don''t see much HDR', '2014-08-19 20:04:43.000000', NULL, 1),
(7253130, 1127288, 17370, '<td valign="top">HDR used to great effect.</td>', 'HDR used to great effect.', '2014-08-20 08:31:03.000000', NULL, 1),
(7253146, 1127006, 54446, '<td valign="top">Distracted by the painting and the blown highlights outside.  Otherwise, good job on the middle tones.   9</td>', 'Distracted by the painting and the blown highlights outside.  Otherwise, good job on the middle tones.   9', '2014-08-20 09:53:59.000000', NULL, 1),
(7253149, 1126954, 54446, '<td valign="top">Great job on this spectacular scene.  Good management of the highlights and yet, well retained detail in the shadows.  Superb DOF. I don''t like the composition with the horizon line near the vertical middle.  Too much foreground.  Too much blue sky above.  The detail of Longs and the front range is an afterthought.</td>', 'Great job on this spectacular scene.  Good management of the highlights and yet, well retained detail in the shadows.  Superb DOF. I don''t like the composition with the horizon line near the vertical middle.  Too much foreground.  Too much blue sky above.  The detail of Longs and the front range is an afterthought.', '2014-08-20 09:57:27.000000', NULL, 1),
(7253150, 1127335, 54446, '<td valign="top">Probably not a great subject for HDR processing, as the BF moves a lot.  Halos and smeared details throughout.</td>', 'Probably not a great subject for HDR processing, as the BF moves a lot.  Halos and smeared details throughout.', '2014-08-20 09:59:10.000000', NULL, 1),
(7253153, 1126991, 54446, '<td valign="top">Unique.</td>', 'Unique.', '2014-08-20 10:05:52.000000', NULL, 1),
(7253205, 1127340, 138253, '<td valign="top">i love this image in the sense of "this would look great hung on a wall".<br/> <br/>it looks like any other day commuting in a big city, except that it''s abandoned and sterile, which is the anti-theses to it''s existence.<br/> <br/>i''ve always found late-night public transit to be like visiting another world, and this is the perfect gateway to that other world.</td>', 'i love this image in the sense of "this would look great hung on a wall". it looks like any other day commuting in a big city, except that it''s abandoned and sterile, which is the anti-theses to it''s existence. i''ve always found late-night public transit to be like visiting another world, and this is the perfect gateway to that other world.', '2014-08-20 12:56:53.000000', NULL, 1),
(7253286, 1127110, 175946, '<td valign="top">Beautiful scene and great colors. The horizon is not straight on this monitor and there appears to be a slight halo around parts of the branches.</td>', 'Beautiful scene and great colors. The horizon is not straight on this monitor and there appears to be a slight halo around parts of the branches.', '2014-08-20 18:36:10.000000', NULL, 1),
