(7253499, 1127278, 19825, '<td valign="top">Lovely crisp detail in the foreground and nice layers in the mountains. Lovely scene.</td>', 'Lovely crisp detail in the foreground and nice layers in the mountains. Lovely scene.', '2014-08-21 17:02:45.000000', NULL, 1),
(7253500, 1127108, 19825, '<td valign="top">Excellent scene. I might have like just a bit more of the trees in the foreground than the tops. But, perhaps not.</td>', 'Excellent scene. I might have like just a bit more of the trees in the foreground than the tops. But, perhaps not.', '2014-08-21 17:04:08.000000', NULL, 1),
(7253501, 1127100, 19825, '<td valign="top">I love the contrasting colors and the detail in the foreground transitioning into the creamy background.</td>', 'I love the contrasting colors and the detail in the foreground transitioning into the creamy background.', '2014-08-21 17:05:21.000000', NULL, 1),
(7253502, 1127288, 147314, '<td valign="top">Fantastic image, it has everything: lovely colours, leading limes, good composition and the processing is spot on for the challenge. 10</td>', 'Fantastic image, it has everything: lovely colours, leading limes, good composition and the processing is spot on for the challenge. 10', '2014-08-21 17:07:23.000000', NULL, 1),
