(7253504, 1127270, 19825, '<td valign="top">Well composed and processed scene. You might consider doing some vertical perspective correction to ease the sensation that the buildings are leaning back. If you haven''t used it before it is a simple adjustment in PS or Elements much like straightening the horizon. Regardless, nice job.</td>', 'Well composed and processed scene. You might consider doing some vertical perspective correction to ease the sensation that the buildings are leaning back. If you haven''t used it before it is a simple adjustment in PS or Elements much like straightening the horizon. Regardless, nice job.', '2014-08-21 17:09:23.000000', NULL, 1),
(7253506, 1127335, 19825, '<td valign="top">Beautiful. It has a bit of a painterly feel to it.</td>', 'Beautiful. It has a bit of a painterly feel to it.', '2014-08-21 17:10:22.000000', NULL, 1),
(7253507, 1127006, 147314, '<td valign="top">Maybe the composition is a bit unusual, but I really like the HDR processing.</td>', 'Maybe the composition is a bit unusual, but I really like the HDR processing.', '2014-08-21 17:10:42.000000', NULL, 1),
(7253508, 1127288, 19825, '<td valign="top">It is hard to beat a lighthouse, pools of reflection, and nice light.</td>', 'It is hard to beat a lighthouse, pools of reflection, and nice light.', '2014-08-21 17:11:23.000000', NULL, 1),
(7253511, 1127215, 147314, '<td valign="top">Being a Dutchman, I''ve never been there. Really must go there once. I like the smoothness of the water, the sky is beautiful, but I find the top right  corner a bit distracting.</td>', 'Being a Dutchman, I''ve never been there. Really must go there once. I like the smoothness of the water, the sky is beautiful, but I find the top right  corner a bit distracting.', '2014-08-21 17:14:38.000000', NULL, 1),
